import React from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { updateField } from '../redux/formSlice';

export default function StepTwo({ next, prev }) {
  const dispatch = useDispatch();
  const { password, confirmPassword } = useSelector(state => state.form);
  const strength = password.length > 5 ? 'Strong' : 'Weak';

  return (
    <>
      <h4>Step 2: Password</h4>
      <input type="password" className="form-control my-2" placeholder="Password" value={password}
        onChange={e => dispatch(updateField({ field: 'password', value: e.target.value }))} />
      <input type="password" className="form-control my-2" placeholder="Confirm Password" value={confirmPassword}
        onChange={e => dispatch(updateField({ field: 'confirmPassword', value: e.target.value }))} />
      <p>Password Strength: <strong>{strength}</strong></p>
      <div className="d-flex justify-content-between">
        <button className="btn btn-secondary" onClick={prev}>← Prev</button>
        <button className="btn btn-primary" onClick={next}>Next →</button>
      </div>
    </>
  );
}
